package com.pillar; import java.util.*; import java.util.function.*; public class Page<T>{ public java.util.List<T> data; public boolean has_more; public String next_cursor; private transient Function<String,Page<T>> loader; public Page(){} public Page(List<T>d, boolean h, String n, Function<String,Page<T>> l){data=d;has_more=h;next_cursor=n;loader=l;} public Iterable<T> autoPagingIterable(){ return () -> new Iterator<>(){ Page<T> p=Page.this; int i=0; public boolean hasNext(){ return p!=null && (i<p.data.size() || p.has_more); } public T next(){ if(i>=p.data.size()){ p=loader.apply(p.next_cursor); i=0;} return p.data.get(i++);} }; } }
